<?php require_once 'config/auth.php'; require_login(); $pageTitle='Panel principal';
$stats=$pdo->query("SELECT COUNT(*) total, COALESCE(SUM(stock_actual<=stock_minimo),0) bajo, COALESCE(SUM(stock_actual),0) unidades FROM producto WHERE estado=1")->fetch();
$movHoy=$pdo->query("SELECT COUNT(*) n FROM movimiento WHERE DATE(fecha)=CURDATE()")->fetch()['n'];
$alerts=$pdo->query("SELECT p.id_producto,p.codigo,p.nombre,p.stock_actual,p.stock_minimo,c.nombre categoria FROM producto p JOIN categoria c ON c.id_categoria=p.id_categoria WHERE p.estado=1 AND p.stock_actual<=p.stock_minimo ORDER BY p.stock_actual ASC,p.nombre LIMIT 8")->fetchAll();
$recent=$pdo->query("SELECT m.fecha,m.tipo,m.cantidad,p.nombre producto,u.nombre usuario FROM movimiento m JOIN producto p ON p.id_producto=m.id_producto JOIN usuario u ON u.id_usuario=m.id_usuario ORDER BY m.fecha DESC LIMIT 8")->fetchAll();
require 'partials/header.php'; ?>
<div class="hero"><div><span class="eyebrow">CONTROL DE INVENTARIO</span><h1>Panel principal</h1><p>Consulta el estado del inventario, registra movimientos y detecta productos con stock bajo.</p></div><div class="hero-actions"><a class="btn primary" href="movimiento.php?tipo=entrada">+ Entrada</a><a class="btn secondary" href="movimiento.php?tipo=salida">− Salida</a></div></div>
<section class="stats"><div class="stat"><span>Productos activos</span><strong><?=e((string)$stats['total'])?></strong></div><div class="stat warning"><span>Productos con stock bajo</span><strong><?=e((string)$stats['bajo'])?></strong></div><div class="stat"><span>Unidades en inventario</span><strong><?=e((string)$stats['unidades'])?></strong></div><div class="stat"><span>Movimientos de hoy</span><strong><?=e((string)$movHoy)?></strong></div></section>
<div class="two-col"><section class="panel"><div class="panel-head"><h2>Alertas de stock</h2><a href="inventario.php?estado=bajo">Ver inventario</a></div><?php if(!$alerts):?><div class="empty">No hay productos en nivel de alerta.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Stock</th><th>Mínimo</th><th>Estado</th></tr></thead><tbody><?php foreach($alerts as $a):?><tr><td><b><?=e($a['nombre'])?></b><small><?=e($a['codigo'])?> · <?=e($a['categoria'])?></small></td><td><?=e((string)$a['stock_actual'])?></td><td><?=e((string)$a['stock_minimo'])?></td><td><span class="badge danger">Reponer</span></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="panel"><div class="panel-head"><h2>Últimos movimientos</h2><?php if(($user['rol']??'')==='propietario'): ?><a href="historial.php">Ver historial</a><?php endif; ?></div><?php if(!$recent):?><div class="empty">Aún no hay movimientos.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th>Cantidad</th></tr></thead><tbody><?php foreach($recent as $m):?><tr><td><?=e(date('d/m/Y H:i',strtotime($m['fecha'])))?></td><td><?=e($m['producto'])?></td><td><span class="badge <?=$m['tipo']==='entrada'?'success':'info'?>"><?=e(ucfirst($m['tipo']))?></span></td><td><?=e((string)$m['cantidad'])?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div>
